unsigned checks{};float maximum_error{};
void check(bool value,const char* why){++checks;if(!value){std::fprintf(stderr,"owner check %u failed: %s\n",checks,why);std::exit(1);}}
std::vector<std::uint8_t> memory(0x800000);
R5900Context context(std::uint32_t pc){R5900Context ctx;ctx.pc=pc;ctx.g[29].lo=0x7f0000;ctx.g[31].lo=0x1234;return ctx;}
void invoke(std::uint32_t pc,std::uint32_t a0=0,std::uint32_t a1=0,std::uint32_t a2=0,std::uint32_t a3=0,std::uint32_t t0=0){auto ctx=context(pc);ctx.g[4].lo=a0;ctx.g[5].lo=a1;ctx.g[6].lo=a2;ctx.g[7].lo=a3;ctx.g[8].lo=t0;PS2Runtime runtime;runtime.lookupFunction(pc)(memory.data(),&ctx,&runtime);ref_write(memory.data(),128,std::uint32_t(ctx.g[2].lo));}
void vector_equal(c::Vec3 x,c::Vec3 y,const char* why){for(const auto pair:{std::pair{x.x,y.x},std::pair{x.y,y.y},std::pair{x.z,y.z}}){const auto error=std::abs(pair.first-pair.second);maximum_error=std::max(maximum_error,error);if(error>0.0002f)std::fprintf(stderr,"native %g original %g\n",double(pair.first),double(pair.second));check(error<=0.0002f,why);}}
void basis(const a::Basis& basis,std::uint32_t at){const std::array<float,16> raw{basis.x.x,basis.x.y,basis.x.z,0,basis.y.x,basis.y.y,basis.y.z,0,basis.z.x,basis.z.y,basis.z.z,0,basis.translation.x,basis.translation.y,basis.translation.z,1};ref_write(memory.data(),at,raw);}
void proxy(const c::Proxy& p,std::uint32_t at){std::fill(memory.begin()+at,memory.begin()+at+196,0);ref_write(memory.data(),at,p.bounds);ref_write(memory.data(),at+32,p.lower);ref_write(memory.data(),at+36,p.upper);memory[at+0x32]=p.priority;}
void compare_proxy(const c::Proxy& p,std::uint32_t at){const auto original=ref_read<c::Quad>(memory.data(),at);if(original!=p.bounds)for(unsigned i=0;i<4;++i)std::fprintf(stderr,"vertex%u native(%d,%d) original(%d,%d)\n",i,p.bounds[i].x,p.bounds[i].z,original[i].x,original[i].z);check(original==p.bounds,"original model-space integer corners");check(p.lower==ref_read<std::int32_t>(memory.data(),at+32)&&p.upper==ref_read<std::int32_t>(memory.data(),at+36),"original derived height copy");check(p.kind==memory[at+0x30]&&p.query_class==memory[at+0x31]&&p.priority==memory[at+0x32],"original derived kinds/class/priority");check(p.active==bool(memory[at+0x3c])&&p.busy==bool(memory[at+0x3d]),"original derived activation/busy");}
void pool(){
    invoke(0x5c1120);o::Proxies native;std::vector<std::pair<o::Handle,std::uint32_t>> ids;std::mt19937 random(0x5c11b0);
    for(unsigned iteration=0;iteration<1500;++iteration){
        if(ids.empty()||(ids.size()<128&&random()%3)){
            const bool prepend=random()%2;o::Record record;record.geometry.identifier=iteration;const auto id=native.create(record,prepend);check(bool(id),"native bounded allocation");invoke(0x5c11b0,prepend);const auto address=ref_read<std::uint32_t>(memory.data(),128);check(address!=0,"original admitted bounded allocation");ref_write(memory.data(),address+0x40,iteration);ids.push_back({*id,address});
        }else{const auto index=random()%ids.size();const auto old=ids[index];check(native.retire(old.first),"native live retire");invoke(0x5c12a0,old.second);check(ref_read<std::uint32_t>(memory.data(),128)==1,"original live retire");check(!native.get(old.first)&&!native.retire(old.first),"native stale reuse rejected");ids.erase(ids.begin()+index);}
        const auto ordered=native.ordered();check(ordered.size()==ids.size(),"native original pool count");auto address=ref_read<std::uint32_t>(memory.data(),0x3b5158);for(const auto& id:ordered){check(address!=0,"original list bounded membership");const auto* p=native.get(id);check(p&&p->geometry.identifier==ref_read<std::uint32_t>(memory.data(),address+0x40),"original prepend/append/reuse creation order");address=ref_read<std::uint32_t>(memory.data(),address+0x2c);}check(address==0,"original list terminates");
    }
    o::Proxies other;check(!ids.empty()&&!other.get(ids.front().first),"foreign room handle refused");native.clear();check(native.size()==0&&!native.get(ids.front().first),"room teardown invalidates handles");
    o::Proxies exhausted(1,1);const auto once=exhausted.create({});check(once&&exhausted.retire(*once)&&!exhausted.create({}),"generation exhaustion refuses identity alias");
}
void derived(){
    std::mt19937 random(0x5c5d30);for(unsigned iteration=0;iteration<1200;++iteration){
        const auto scalar=[&]{return float(int(random()%10001)-5000)/10;};const float angle=float(random()%65536)*0.0000958738019107841f,scale=0.5f+float(random()%4)*0.5f;
        a::Basis model;model.x={std::cos(angle)*scale,0,-std::sin(angle)*scale};model.z={std::sin(angle),0,std::cos(angle)};model.translation={scalar(),0,scalar()};
        c::Proxy source;source.bounds={c::Point{-120,-50},c::Point{120,-50},c::Point{120,100},c::Point{-120,100}};source.lower=-100;source.upper=200;source.priority=std::uint8_t(random()%10);
        for(auto& point:source.bounds){const auto transformed=model.point({float(point.x),0,float(point.z)});point=*c::integer_xz(transformed);}
        for(const auto pc:{0x5c5d30u,0x5c6100u}){invoke(0x5c1120);proxy(source,0x10000);basis(model,0x49fa10);ref_write(memory.data(),0x1004c,0u);ref_write(memory.data(),0x10044,0u);invoke(pc,0x10000);const auto at=ref_read<std::uint32_t>(memory.data(),128);const auto result=pc==0x5c5d30?o::depth_extension(source,model):o::depth_sixty(source,model);check(result.has_value()&&at!=0,"original defined model-space region admission");if(result->bounds!=ref_read<c::Quad>(memory.data(),at))std::fprintf(stderr,"iteration%u pc%x angle%g scale%g\n",iteration,pc,double(angle),double(scale));if(result->bounds!=ref_read<c::Quad>(memory.data(),at)){for(unsigned k=0;k<4;++k){const auto v=ref_read<c::Vec3>(memory.data(),0x7f0000-0x130+0xd0+12*k);std::fprintf(stderr,"local%u %g %g %g\n",k,double(v.x),double(v.y),double(v.z));}}compare_proxy(*result,at);}
        proxy(source,0x10000);basis(model,0x49fa10);ref_write(memory.data(),0x10060,0u);invoke(0x5c66c0,0x10000);const auto result=o::reproject_middle(source.bounds,model);check(result&&*result==ref_read<c::Quad>(memory.data(),0x10000),"original middle-only corner reprojection");
    }
    c::Proxy source;source.bounds={c::Point{-1,20000},c::Point{1,20000},c::Point{1,30000},c::Point{-1,30000}};check(!o::depth_extension(source,{}),"undefined original no-near-depth index rejected");check(!o::depth_sixty(source,{},true),"original existing binding refuses second region");a::Basis zero;zero.x={};check(!o::depth_sixty(source,zero),"degenerate original inverse excluded from admitted native geometry");
}
c::response::Grid wall_grid(){std::vector<std::byte> bytes(128);const auto word=[&](unsigned at,std::uint32_t v){std::memcpy(bytes.data()+at,&v,4);};word(8,1000);word(12,1000);word(16,1);word(20,1);word(24,0);word(28,0);word(32,32);word(36,48);word(40,36);word(44,0);word(48,0xffffffff);c::response::Triangle t{0x1ffff,{c::Vec3{500,-500,0},c::Vec3{500,500,0},c::Vec3{500,0,1000}},{1,0,0},-500};std::memcpy(bytes.data()+56,&t,56);return c::response::Grid::import(bytes);}
void wall(){const auto grid=wall_grid();for(unsigned i=0;i<200;++i){o::WallState state;state.position={float(470+i%61),20,400};state.previous={state.position.x-5,20,400};state.local_center={float(i%3),1,2};state.previous_center_offset={1,1,1};state.radius=25;state.include=0x1ffff;state.disabled=i%5==0;state.dynamic_kind_gate=i%2;const auto before=state;a::Basis model;model.x.x=2;
    std::fill(memory.begin()+0x10000,memory.begin()+0x11000,0);basis(model,0x10050);ref_write(memory.data(),0x10038,state.position);ref_write(memory.data(),0x10044,state.previous);ref_write(memory.data(),0x101ac,state.local_center);ref_write(memory.data(),0x101b8,state.radius);ref_write(memory.data(),0x101cc,state.previous_center_offset);ref_write(memory.data(),0x10190,state.include);ref_write(memory.data(),0x10194,state.exclude);ref_write(memory.data(),0x1054a,std::uint16_t(state.disabled));memory[0x10002]=state.dynamic_kind_gate?2:0;
    ownership_fixture::result=o::move_against_walls(state,model,grid,{});invoke(0x5da420,0x10000);vector_equal(state.position,ref_read<c::Vec3>(memory.data(),0x10038),"original actor wall wrapper X/Z result");vector_equal(state.previous_center_offset,ref_read<c::Vec3>(memory.data(),0x101cc),"original disabled/enabled cached offset refresh");check(state.contact==bool(memory[0x1016c]&1),"original wall contact flag");if(!state.disabled){const auto offset=model.direction(before.local_center);vector_equal(ownership_fixture::current,{before.position.x+offset.x,before.position.y+offset.y,before.position.z+offset.z},"original wall current center argument");vector_equal(ownership_fixture::previous,{before.previous.x+before.previous_center_offset.x,before.previous.y+before.previous_center_offset.y,before.previous.z+before.previous_center_offset.z},"original wall previous center argument");check(ownership_fixture::radius==before.radius&&ownership_fixture::include==before.include&&ownership_fixture::exclude==before.exclude&&bool(ownership_fixture::gate)==before.dynamic_kind_gate,"original wall mask/radius/class gate arguments");}}
}
void regions(){
    using namespace reo::native::gameplay_actors;EntityStore entities;const auto actor=entities.create(std::make_unique<Entity>()).id;const c::Quad bounds{c::Point{0,0},c::Point{100,0},c::Point{100,100},c::Point{0,100}};
    const std::array<std::uint32_t,4> entries{0x5c62f0,0x5c63b0,0x5c6480,0x5c6550};
    for(unsigned k=0;k<4;++k){invoke(0x5c1120);ref_write(memory.data(),0x20000,bounds);memory[0x10240]=53;invoke(entries[k],0x10000,0x20000,std::uint32_t(-25),200,7);const auto at=ref_read<std::uint32_t>(memory.data(),128);const auto record=o::owned_region(std::uint8_t(0x80+k),bounds,-25,200,actor,53,7);compare_proxy(record.geometry,at);check(record.owner==actor&&(!record.owner_snapshot||*record.owner_snapshot==memory[at+0x44]),"owned region immutable identity/snapshot");if(k==2)check(record.extra&&*record.extra==memory[at+0x45],"original extra-byte constructor");}
    o::Proxies proxies;c::Proxy p;p.bounds=bounds;p.lower=0;p.upper=100;p.kind=0;p.query_class=0;p.priority=2;o::Record record;record.geometry=p;const auto first=*proxies.create(record),last=*proxies.create(record);std::array<c::ProxyState,2> states; c::ActorQuery query;query.point={50,50,50};query.position=query.point;query.query_class=0;const auto selected=proxies.select(query,actor,states);check(selected&&selected->proxy==last&&selected->actor==actor,"mutable owner newest equal priority native actor selection");record.geometry.active=false;check(proxies.replace(last,record),"native proxy activation update");const auto changed=proxies.select(query,actor,states);check(changed&&changed->proxy==first,"activation invalidates cached native snapshot");check(proxies.retire(last)&&!proxies.replace(last,record),"retired activation cannot mutate reused slot");
}
